#!/usr/bin/env node
/**
 * Bundles `scripts/terminal-webview/terminal-emulator-entry.ts` — the
 * in-WebView `xterm.js` runtime — into a single self-contained HTML string
 * exported from `src/features/terminal/terminal-webview-html.gen.ts`, which
 * `react-native-webview`'s `source={{ html }}` loads (T32S11).
 *
 * Run it after changing the entry, or after bumping `@xterm/xterm` /
 * `@xterm/addon-fit`:
 *
 *   node apps/android/scripts/build-terminal-webview-html.mjs
 *
 * The generated file is named `*.gen.ts` so the repository's formatter
 * ignores it (`.oxfmtrc.json`'s `ignorePatterns`), and is committed so the
 * Android build does not depend on this script having run.
 */
import esbuild from "esbuild";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const appRoot = path.resolve(here, "..");
const entry = path.join(here, "terminal-webview/terminal-emulator-entry.ts");
const output = path.join(appRoot, "src/features/terminal/terminal-webview-html.gen.ts");

const result = await esbuild.build({
  entryPoints: [entry],
  bundle: true,
  write: false,
  format: "iife",
  platform: "browser",
  target: ["chrome100"],
  minify: true,
  loader: { ".css": "text" },
  logLevel: "warning",
});

const javascript = result.outputFiles[0]?.text;
if (!javascript) {
  throw new Error("terminal webview bundle produced no JavaScript");
}

const html = `<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta
      name="viewport"
      content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover"
    />
    <style>
      html, body { margin: 0; padding: 0; height: 100%; background: transparent; overflow: hidden; }
      #terminal { position: absolute; inset: 0; }
    </style>
  </head>
  <body>
    <div id="terminal"></div>
    <script>${javascript}</script>
  </body>
</html>`;

const contents = `// Generated by apps/android/scripts/build-terminal-webview-html.mjs.
// Do not edit by hand — edit scripts/terminal-webview/terminal-emulator-entry.ts
// and re-run that script instead.

export const terminalWebViewHtml = ${JSON.stringify(html)};
`;

await fs.writeFile(output, contents);
console.log(`Wrote ${path.relative(appRoot, output)} (${html.length} bytes)`);
